impl AeronDriverContext<CResource<aeron_driver_context_t>> {
    #[inline]
    #[doc = "Create a `AeronDriverContext` struct and initialize with default values."]
    #[doc = ""]
    #[doc = " \n# Return\n 0 for success and -1 for error."]
    pub fn new() -> Result<Self, AeronCError> {
        let resource_constructor = ManagedCResource::<aeron_driver_context_t>::new(
            move |ctx_field| unsafe {
                #[cfg(feature = "log-c-bindings")]
                {
                    let log_args =
                        [concat!("context", ": ", stringify!(*mut *mut aeron_driver_context_t)).to_string()].join(", ");
                    log::info!("{}({})", stringify!(aeron_driver_context_init), log_args);
                }
                aeron_driver_context_init(ctx_field)
            },
            Some(Box::new(move |ctx_field| unsafe {
                #[cfg(feature = "log-c-bindings")]
                {
                    let log_args =
                        [concat!("context", ": ", stringify!(*mut aeron_driver_context_t)).to_string()].join(", ");
                    log::info!("{}({})", stringify!(aeron_driver_context_close), log_args);
                }
                aeron_driver_context_close(*ctx_field)
            })),
            false,
        )?;
        let result = Self {
            inner: CResource::new(ResourceRef::new(resource_constructor)).into(),
        };
        Ok(result)
    }
}
impl AeronDriverContext {
    #[inline]
    pub fn validate_mtu_length(mtu_length: u64) -> Result<i32, AeronCError> {
        unsafe {
            #[cfg(feature = "log-c-bindings")]
            log::info!(
                "{}({})",
                stringify!(aeron_driver_context_validate_mtu_length),
                [format!("{} = {:?}", "mtu_length", mtu_length)].join(", ")
            );
            let result = aeron_driver_context_validate_mtu_length(mtu_length.into());
            #[cfg(feature = "log-c-bindings")]
            log::info!("  -> {:?}", result);
            if result < 0 {
                return Err(AeronCError::from_code(result));
            } else {
                return Ok(result);
            }
        }
    }
}
