impl AeronDriver<CResource<aeron_driver_t>> {
    #[inline]
    #[doc = "Create a `AeronDriver` struct and initialize from the `AeronDriverContext` struct."]
    #[doc = ""]
    #[doc = " The given `AeronDriverContext` struct will be used exclusively by the driver. Do not reuse between drivers."]
    #[doc = ""]
    #[doc = "# Parameters\n \n - `context` to use for initialization."]
    #[doc = " \n# Return\n 0 for success and -1 for error."]
    pub fn new(context: &AeronDriverContext) -> Result<Self, AeronCError> {
        let __context_use = context
            .inner
            .as_owned()
            .ok_or_else(|| AeronCError::with_message(-1, "client requires an owned context"))?
            .reserve_context()?;
        let context_copy = context;
        let context: *mut aeron_driver_context_t = context.into();
        let resource_constructor = ManagedCResource::<aeron_driver_t>::new(
            move |ctx_field| unsafe {
                #[cfg(feature = "log-c-bindings")]
                {
                    let log_args = [
                        concat!("driver", ": ", stringify!(*mut *mut aeron_driver_t)).to_string(),
                        concat!("context", ": ", stringify!(*mut aeron_driver_context_t)).to_string(),
                    ]
                    .join(", ");
                    log::info!("{}({})", stringify!(aeron_driver_init), log_args);
                }
                aeron_driver_init(ctx_field, context)
            },
            Some(Box::new(move |ctx_field| unsafe {
                #[cfg(feature = "log-c-bindings")]
                {
                    let log_args = [concat!("driver", ": ", stringify!(*mut aeron_driver_t)).to_string()].join(", ");
                    log::info!("{}({})", stringify!(aeron_driver_close), log_args);
                }
                aeron_driver_close(*ctx_field)
            })),
            false,
        )?;
        __context_use.commit();
        let result = Self {
            inner: CResource::new(ResourceRef::new(resource_constructor)).into(),
        };
        result.inner.add_handle_dependency(context_copy);
        Ok(result)
    }
}
