#[cfg(test)]
mod timespec_allocation_tests {
    use super::*;
    use serial_test::file_serial;
    #[test]
    #[file_serial(global)]
    fn test_new_on_stack() {
        crate::test_alloc::assert_no_allocation(|| {
            for _ in 0..100 {
                let _ = unsafe { Timespec::new_zeroed_on_stack() };
            }
        });
    }
    #[test]
    #[file_serial(global)]
    fn test_default() {
        crate::test_alloc::assert_no_allocation(|| {
            for _ in 0..100 {
                let _ = Timespec::default();
            }
        });
    }
}
